const trg = $('When Executed by Another Workflow').first().json;
const ZONE = 'Asia/Yekaterinburg';
const chatId = String(trg.chat_id || '').trim();
const action = String(trg.action || '').toLowerCase().trim();
const out = (decision, extra = {}) => [{ json: { ...trg, decision, eventId: '', info: '', ...extra } }];
if (!chatId) return out('bad_input');
const start = DateTime.fromISO(String(trg.start_time), { zone: ZONE });
if (!start.isValid) return out('bad_input');
const dur = Number(trg.duration) > 0 ? Number(trg.duration) : 60;
const end = start.plus({ minutes: dur });
const now = DateTime.now().setZone(ZONE);
if (action !== 'delete' && start < now.minus({ minutes: 5 })) return out('past');

const toDt = v => DateTime.fromISO(v || '', { zone: ZONE });
const events = $input.all().map(i => i.json)
  .filter(e => e && e.id && e.status !== 'cancelled')
  .map(e => ({ e, s: toDt(e.start && (e.start.dateTime || e.start.date)), f: toDt(e.end && (e.end.dateTime || e.end.date)) }))
  .filter(x => x.s.isValid && x.f.isValid);

const idRe = new RegExp('(^|\\D)' + chatId + '(\\D|$)');
const isMine = x => idRe.test(String(x.e.description || ''));
const overlaps = x => x.s < end && x.f > start;
const fmt = x => x.s.setLocale('ru').toFormat('d MMMM, HH:mm');
const mine = events.filter(x => isMine(x) && x.f > now).sort((a, b) => a.s.toMillis() - b.s.toMillis());

let decision, target = null, info = '';
if (action === 'delete' || action === 'update') {
  let pool = mine;
  const ref = action === 'delete' ? start : (trg.old_start_time ? toDt(String(trg.old_start_time)) : null);
  if (ref && ref.isValid) {
    const near = mine.filter(x => Math.abs(x.s.toMillis() - ref.toMillis()) < 30 * 60000);
    pool = near.length ? near : mine.filter(x => x.s.hasSame(ref, 'day'));
  }
  if (!pool.length) decision = action === 'delete' ? 'noop_delete' : 'noop_update';
  else if (pool.length > 1) { decision = 'ambiguous'; info = pool.map(fmt).join('; '); }
  else {
    target = pool[0];
    decision = action;
    if (action === 'update' && events.some(x => x.e.id !== target.e.id && overlaps(x))) decision = 'busy';
  }
} else if (action === 'get') {
  decision = events.some(overlaps) ? 'busy' : 'free';
} else if (action === 'create') {
  const hit = events.filter(overlaps);
  if (hit.some(x => !isMine(x))) decision = 'busy';
  else if (hit.length) decision = 'exists';
  else decision = 'create';
} else {
  decision = 'bad_input';
}

const old = target ? target.e : null;
const oldDesc = String((old && old.description) || '');
const pick = re => (oldDesc.match(re) || [])[1] || '';
const service = trg.service || pick(/Услуга:\s*(.+)/);
const phone = trg.telephon_number || pick(/Телефон:\s*(.+)/);
const name = trg.name || ((old && old.summary) || '').split(': ').slice(1).join(': ');
return out(decision, {
  eventId: target ? target.e.id : '',
  info,
  startIso: start.toISO(),
  endIso: end.toISO(),
  summary: service + ': ' + name,
  description: 'Телефон: ' + phone + '\nChat ID: ' + chatId + '\nПлатформа: ' + (trg.platform || '') + '\nУслуга: ' + service
});

