parameters.text:
={{ (() => {
  const d = $('Decide').first().json;
  const old = $('Get many events').all().map(i => i.json).find(e => e && e.id && e.id === d.eventId);
  const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const fmt = v => DateTime.fromISO(v, { zone: 'Asia/Yekaterinburg' }).setLocale('ru').toFormat('d MMMM (ccc), HH:mm');
  const del = d.decision === 'delete';
  const oldStart = old ? ((old.start && (old.start.dateTime || old.start.date)) || '') : '';
  const src = del ? String((old && old.description) || '') : String(d.description || '');
  const pick = re => (src.match(re) || [])[1] || '';
  const summary = del ? String((old && old.summary) || d.summary || '') : String(d.summary || '');
  const svc = summary.split(': ')[0];
  const name = summary.split(': ').slice(1).join(': ') || d.name || '';
  const phone = pick(/Телефон:\s*(.+)/) || d.telephon_number || '';
  const head = { create: '🆕 <b>НОВАЯ ЗАПИСЬ</b>', update: '🔄 <b>ПЕРЕНОС ЗАПИСИ</b>', delete: '❌ <b>ОТМЕНА ЗАПИСИ</b>' }[d.decision];
  const client = d.platform === 'tg' ? '<a href="tg://user?id=' + esc(d.chat_id) + '">' + esc(name) + '</a>' : esc(name);
  const lines = [head, '👤 <b>Клиент:</b> ' + client, '💆 <b>Услуга:</b> ' + esc(svc)];
  if (d.decision === 'update') {
    if (oldStart) lines.push('🕒 <b>Было:</b> ' + fmt(oldStart));
    lines.push('🕒 <b>Стало:</b> ' + fmt(d.startIso));
  } else {
    lines.push('🕒 <b>Время:</b> ' + fmt(del && oldStart ? oldStart : d.startIso));
  }
  lines.push('📞 <b>Телефон:</b> ' + esc(phone));
  lines.push('💬 <b>Платформа:</b> ' + esc(d.platform || '') + ', ID ' + esc(d.chat_id));
  return lines.join('\n');
})() }}

